class Logger {

    private static Logger instance;

    private Logger() {
        // pretend this opens a file handle
    }

    public static Logger getInstance() {
        if (instance == null) {           // both threads can pass this check
            instance = new Logger();      // both threads can reach this line
        }
        return instance;
    }
}

// Thread A and Thread B both call Logger.getInstance() at almost
// the same moment. Both can read instance as null before either
// write completes, so two Logger objects get created.

public class Main {
    public static void main(String[] args) throws InterruptedException {
        int threadCount = 8;
        Logger[] results = new Logger[threadCount];
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            final int idx = i;
            threads[i] = new Thread(() -> results[idx] = Logger.getInstance());
        }
        for (Thread t : threads) t.start();
        for (Thread t : threads) t.join();

        long distinctInstances = java.util.Arrays.stream(results).distinct().count();
        System.out.println("Distinct Logger instances created: " + distinctInstances);
        System.out.println("(On a real JVM under load this can be more than 1, " +
                "which is the whole point of this example.)");
    }
}

