// JavaScript is single threaded per event loop, so this exact
// interleaving does not happen the same way it does in Java.
// The conceptual equivalent shows up with async work: if
// getInstance does something asynchronous before assigning the
// field, two concurrent callers can both start building the
// object before either finishes.
class Logger {
  static instance = null;

  static async getInstance() {
    if (Logger.instance === null) {
      const built = await Logger.create(); // await yields control here
      Logger.instance = built;             // a second caller can slip in above
    }
    return Logger.instance;
  }

  static async create() {
    return new Logger();
  }
}

