Logger* Logger::instance = nullptr;

// Thread A and Thread B both call Logger::getInstance() at almost
// the same moment. Both can read instance as nullptr before either
// write completes, so two Logger objects can get created.

int main() {
    const int threadCount = 8;
    std::vector<Logger*> results(threadCount, nullptr);
    std::vector<std::thread> threads;

    for (int i = 0; i < threadCount; i++) {
        threads.emplace_back([&results, i]() {
            results[i] = Logger::getInstance();
        });
    }
    for (auto& t : threads) t.join();

    std::set<Logger*> distinct(results.begin(), results.end());
    std::cout << "Distinct Logger instances created: " << distinct.size() << std::endl;
    std::cout << "(On real concurrent hardware this can be more than 1, "
              << "which is the whole point of this example.)" << std::endl;
    return 0;
}

