// The equivalent overcorrection in JavaScript is wrapping every
// access in a mutex-style lock even after the value is already
// settled. Shown here with a simple async lock to mirror the idea.
class Logger {
  static instance = null;
  static lock = Promise.resolve();

  static async getInstance() {
    // every single call chains onto the lock, forever, even
    // though only the very first call actually needs to wait
    const result = await (Logger.lock = Logger.lock.then(async () => {
      if (Logger.instance === null) {
        Logger.instance = new Logger();
      }
      return Logger.instance;
    }));
    return result;
  }
}

