// JavaScript rarely needs this pattern because module level
// singletons already get exactly one initialization, guaranteed
// by the module loader. The conceptual double check shows up when
// initialization is asynchronous and you want to avoid duplicate
// in-flight work.
class Logger {
  static instance = null;
  static creating = null;

  static async getInstance() {
    if (Logger.instance !== null) return Logger.instance; // first check

    if (Logger.creating === null) {                        // guard the create step
      Logger.creating = (async () => new Logger())();
    }
    Logger.instance = await Logger.creating;                // second check equivalent
    return Logger.instance;
  }
}

