    // without volatile, a second thread could observe a
    // half constructed Logger through this field
    private static volatile Logger instance;

    private final String startedAt;

    private Logger() {
        startedAt = "logger-ready";
    }

    public static Logger getInstance() {
        if (instance == null) {
            synchronized (Logger.class) {
                if (instance == null) {
                    instance = new Logger();  // safe publish, thanks to volatile
                }
            }
        }
        return instance;
    }

    public String getStartedAt() {
        return startedAt;
    }
}

