    public static void main(String[] args) throws InterruptedException {
        int threadCount = 8;
        String[] results = new String[threadCount];
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            final int idx = i;
            threads[i] = new Thread(() -> results[idx] = Logger.getInstance().getStartedAt());
        }
        for (Thread t : threads) t.start();
        for (Thread t : threads) t.join();

        boolean allFullyConstructed = java.util.Arrays.stream(results)
                .allMatch(s -> s.equals("logger-ready"));
        System.out.println("Every thread observed a fully constructed Logger: " + allFullyConstructed);
    }
}

