import threading

# CPython protects references with the GIL, so a partially
# constructed object cannot be observed through a normal attribute
# assignment the way it can in Java without volatile. Other Python
# implementations without a GIL would need an explicit memory
# barrier or a lock around both the check and the assignment.
class Logger:
    _instance = None
    _lock = threading.Lock()

    def __init__(self):
        self.started_at = "logger-ready"

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = Logger()  # safe publish under the lock
        return cls._instance


if __name__ == "__main__":
    results = [None] * 8
    threads = []

    def worker(idx):
        results[idx] = Logger.get_instance().started_at

    for i in range(8):
        t = threading.Thread(target=worker, args=(i,))
        threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    all_fully_constructed = all(r == "logger-ready" for r in results)
    print(f"Every thread observed a fully constructed Logger: {all_fully_constructed}")

