#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <atomic>
#include <string>

class Logger {
private:
    // without an atomic/acquire-release pair, a second thread could
    // observe a half constructed Logger through this pointer
    static std::atomic<Logger*> instance;
    static std::mutex mtx;

    std::string startedAt;

    Logger() : startedAt("logger-ready") {}

public:
    static Logger* getInstance() {
        Logger* result = instance.load(std::memory_order_acquire);
        if (result == nullptr) {
            std::lock_guard<std::mutex> lock(mtx);
            result = instance.load(std::memory_order_relaxed);
            if (result == nullptr) {
                result = new Logger();
                instance.store(result, std::memory_order_release); // safe publish
            }
        }
        return result;
    }

    const std::string& getStartedAt() const { return startedAt; }
};

std::atomic<Logger*> Logger::instance{nullptr};
std::mutex Logger::mtx;

int main() {
    const int threadCount = 8;
    std::vector<std::string> results(threadCount);
    std::vector<std::thread> threads;

    for (int i = 0; i < threadCount; i++) {
        threads.emplace_back([&results, i]() {
            results[i] = Logger::getInstance()->getStartedAt();
        });
    }
    for (auto& t : threads) t.join();

    bool allFullyConstructed = true;
    for (auto& r : results) {
        if (r != "logger-ready") allFullyConstructed = false;
    }
    std::cout << "Every thread observed a fully constructed Logger: " << allFullyConstructed << std::endl;
    return 0;
}

