#include <iostream>
#include <string>

// C++ has no direct equivalent of a Java enum singleton (enums in
// C++ cannot carry methods), so the closest idiomatic match is a
// class whose copy and move operations are explicitly deleted, and
// whose single instance is a static value, not a pointer, so there
// is no separate heap allocation step for anything to race on
class Logger {
public:
    static Logger& instance() {
        static Logger INSTANCE;
        return INSTANCE;
    }

    void log(const std::string& message) {
        std::cout << message << std::endl;
    }

    Logger(const Logger&) = delete;
    Logger& operator=(const Logger&) = delete;

private:
    Logger() = default;
};

int main() {
    // guaranteed to be constructed exactly once, safely, even
    // under concurrent first access, and impossible to copy
    Logger::instance().log("application started");
    return 0;
}
